import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-12-16 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-12-16 :: Ceph Orchestration Meeting","date":"2019-12-16T00:00:00.000Z","updated":"2019-12-16T00:00:00.000Z","tags":["Ceph","Distributed Storage","ORchestration","Ceph Manager","Ceph Orchestrator"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-12-16_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-12-16_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),r={name:"posts/2019/2019-12-16_-_-_Ceph_Orchestration_Meeting.md"};function o(n,e,s,h,p,u){return l(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间与参与人员" tabindex="-1">会议时间与参与人员 <a class="header-anchor" href="#会议时间与参与人员" aria-label="Permalink to &quot;会议时间与参与人员&quot;">​</a></h4><ul><li><strong>时间：</strong> 会议开始有几分钟延迟。</li><li><strong>参与人员：</strong> 由主持人主持，Brooke等团队成员参与。</li></ul><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>Ceph 1.2 版本发布计划</strong></p><ul><li>Brooke 计划在未来几天内完成1.2版本的发布，目前正在进行最后的修复工作。</li><li>讨论了自动删除OSD的代码变更，决定不再自动删除OSD，以避免数据丢失，改为用户手动操作。</li></ul></li><li><p><strong>设计文档与未来规划</strong></p><ul><li>讨论了OSD移除的设计文档，正在等待反馈和重新审视。</li><li>提及了多站点RGW的设计进展，由Radia负责，可能对未来的对象存储CR有影响。</li></ul></li><li><p><strong>Ceph Orchestrator 与 Dashboard 集成</strong></p><ul><li>讨论了将新的CR添加到对象存储CR中，以支持跨集群配置。</li><li>计划由Elly开放设计PR，以便团队成员积极参与讨论和反馈。</li></ul></li><li><p><strong>Ceph Manager 模块的测试与集成</strong></p><ul><li>讨论了Ceph Manager模块的测试问题，目前缺乏有效的QA和CI集成。</li><li>提出了在Rook CI中集成Ceph Manager模块的建议，以便进行更有效的测试。</li></ul></li><li><p><strong>其他技术细节与问题</strong></p><ul><li>讨论了Ceph Orchestrator的并行化问题，以及如何在多节点环境中进行有效部署和管理。</li><li>提及了Ganesha的集成问题，计划在未来进行更深入的探讨和实施。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>不再自动删除OSD，改为用户手动操作。</li><li>由Elly在本周内开放设计PR。</li><li>在Rook CI中集成Ceph Manager模块的建议。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完成Ceph 1.2版本的发布工作。</li><li>Elly将在本周内开放设计PR。</li><li>探讨和实施Ceph Manager模块的测试和集成方案。</li><li>对Ganesha的集成问题进行更深入的探讨和实施。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中还讨论了一些技术细节和问题，但未形成具体的决定或行动计划。</li><li>会议结束时，主持人感谢大家的参与，并宣布会议结束。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><ul><li><strong>时间：</strong> 会议在讨论完所有议题后结束。</li><li><strong>参与人员：</strong> 所有参与人员确认会议结束。</li></ul>',13)])])}const c=a(r,[["render",o]]);export{d as __pageData,c as default};
